# Service layer for Asana integrations
from typing import Dict
from .client import AsanaClient
from .schema import TaskParams, SectionParams, ApiResponse

class AsanaService:
    def __init__(self, client: AsanaClient):
        self.client = client

    def add_task_to_section(self, section_uid: str, task_uid: str) -> ApiResponse:
        endpoint = f"/sections/{section_uid}/addTask"
        data = {
            "data": {
                "task": task_uid
            }
        }
        response = self.client.post_request(endpoint, data)
        return ApiResponse(**response)

    def remove_follower_for_task(self, task_uid: str, user_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/removeFollowers"
        data = {
            "data": {
                "followers": [user_uid]
            }
        }
        response = self.client.post_request(endpoint, data)
        return ApiResponse(**response)

    def remove_project_for_task(self, task_uid: str, project_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/removeProject"
        data = {
            "data": {
                "project": project_uid
            }
        }
        response = self.client.post_request(endpoint, data)
        return ApiResponse(**response)

    def get_tasks_for_section(self, section_uid: str) -> ApiResponse:
        endpoint = f"/sections/{section_uid}/tasks"
        response = self.client.get_request(endpoint)
        return ApiResponse(**response)

    def get_subtasks_for_task(self, task_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/subtasks"
        response = self.client.get_request(endpoint)
        return ApiResponse(**response)

    def get_tasks_for_user_task_list(self, user_task_list_uid: str) -> ApiResponse:
        endpoint = f"/user_task_list/{user_task_list_uid}/tasks"
        response = self.client.get_request(endpoint)
        return ApiResponse(**response)

    def get_stories_for_task(self, task_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/stories"
        response = self.client.get_request(endpoint)
        return ApiResponse(**response)

    def duplicate_task(self, task_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/duplicate"
        response = self.client.post_request(endpoint)
        return ApiResponse(**response)

    def remove_dependencies_for_task(self, task_uid: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/removeDependencies"
        response = self.client.post_request(endpoint)
        return ApiResponse(**response)

    def remove_tag_for_task(self, task_uid: str, tag: str) -> ApiResponse:
        endpoint = f"/tasks/{task_uid}/removeTag"
        data = {"data": {"tag": tag}}
        response = self.client.post_request(endpoint, data)
        return ApiResponse(**response)

