# FastAPI routes for Asana integrations
from fastapi import APIRouter, Depends, HTTPException, Body
from typing import Dict, Any
from .service import AsanaService
from .client import AsanaClient
from .schema import TaskParams, SectionParams, ApiResponse
from pydantic import ValidationError

router = APIRouter(prefix="/asana", tags=["asana"])

async def get_asana_service() -> AsanaService:
    client = AsanaClient(api_key="YOUR_API_KEY")
    return AsanaService(client)

@router.post("/addTaskForSection", response_model=ApiResponse)
async def add_task_for_section(
    params: SectionParams = Body(...),
    service: AsanaService = Depends(get_asana_service)
):
    try:
        return service.add_task_to_section(params.section_gid, params.data["task"])
    except ValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

