async def remove_follower_for_task(
    params: Dict[str, Any] = Body(...),
    service: AsanaService = Depends(get_asana_service)
):
    try:
        task_uid = params["task_gid"]
        user_uid = params["user_gid"]
        return service.remove_follower_for_task(task_uid, user_uid)
